let bridge=new Bridge(),selectedAdapter='esp32',boardInfo=null,calAddress=0x80;let device=null,latest=null,snapshot=null,liveTimer=null,hardwareBusy=false,historyRows=[];let chosenAddress=0x6d;let labBase=null,labPlan=null,labChecks=[],labExpected=null,labAttempted=false,labVerified=false,labRamChanged=false,labUnsafe=false,labEdit='{}',recording=false,logMeta={reference:null,note:''};
