function invalidate(){s.fit=null;s.results=null;s.output=null;}
function resetPoints(){s.points=[];s.checks=[];s.selected=0;s.source='manual';invalidate();}
function setModel(v){if(v===s.model)return;if(!bridge.closed||hardwareBusy){render();message('Zuerst Adapter trennen.','warn');return;}if((s.points.length||s.log.length)&&!confirm('Modell wechseln und aktuelle Messdaten verwerfen?')){render();return;}s.model=v;chosenAddress=profiles[v]?.addresses.at(-1)||0x6d;resetPoints();s.log=[];s.diag=null;historyRows=[];resetLab();const u=new URL(location.href);u.searchParams.set('model',v);history.replaceState(null,'',u);render();}
function plan(){if(!finite(s.lo,s.hi)||s.hi<=s.lo||s.temps.slice(0,s.t).some(x=>!valid(x))||new Set(s.temps.slice(0,s.t)).size!==s.t)throw Error('Druckbereich und unterschiedliche Temperatur-Sollwerte prüfen.');if(!s.points.length)s.points=Array.from({length:s.tk0?3:s.p*s.t},(_,i)=>({reference:s.lo+(s.hi-s.lo)*(i%s.p)/(s.p-1),targetTemp:s.temps[Math.floor(i/s.p)],raw:null,temp:null}));}
function hideSettings(){ $('settingsPanel').hidden=true;$('settingsOpen').setAttribute('aria-expanded','false');}
function toggleView(){if(hardwareBusy)return;hideSettings();classic=!classic;render()}
function home(){if(hardwareBusy)return;stopLive();hideSettings();s.task='home';s.step=0;render()}
function go(i){if(hardwareBusy)return;stopLive();if(i===0)return home();if(i>=4&&!s.points.length){try{plan()}catch(e){message(e.message,'error');return;}}s.task='calibration';s.step=i;render();}
function task(k){if(hardwareBusy)return;stopLive();hideSettings();if(k==='calibration'){s.task=k;s.step=1}else{s.task=k;s.step=0}render()}
function download(name,data,type='application/json'){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function report(){return {version:'0.5.0',mode:'offline-fit',hardwareRead:s.points.some(q=>q.acquisition?.source==='chip'),model:s.model,source:s.source,hardwareProgrammed:labVerified&&s.model==='nsa2860x',hardwareProgrammingAttempted:labAttempted&&s.model==='nsa2860x',laboratoryProgrammingSeparateFromOfflineFit:true,createdAt:new Date().toISOString(),range:[s.lo,s.hi],unit:s.unit,pressureOrder:s.p-1,temperatureOrder:s.t-1,thermalModel:s.tk0?'TK0-only':'tensor',temperatureTargets:s.temps.slice(0,s.t),points:s.points,fit:s.fit,tolerancePercent:s.tol,verification:s.results,outputPlan:s.output,verificationStatus:s.results?(s.results.every(q=>q.pass)?'within_offline_tolerance':'failed'):'not_verified'};}
function archiveRead(){try{return JSON.parse(localStorage.getItem('novo-archive-v1')||'[]')}catch{return []}}
function archiveSave(r){const a=archiveRead();a.unshift(r);localStorage.setItem('novo-archive-v1',JSON.stringify(a));message('Lokal archiviert.','success')}
function exportReport(){if(!s.fit)throw Error('Zuerst Koeffizienten berechnen.');download('novosense-calibration.json',JSON.stringify(report(),null,2))}
function csv(rows,name){if(!rows.length)throw Error('Keine Messdaten vorhanden.');const keys=[...new Set(rows.flatMap(Object.keys))];const cell=v=>{let x=String(v??'');if(typeof v==='string'&&/^[=+\-@\t\r]/.test(x))x="'"+x;return '"'+x.replaceAll('"','""')+'"'};download(name,[keys.map(cell).join(';'),...rows.map(r=>keys.map(k=>cell(r[k])).join(';'))].join('\n'),'text/csv;charset=utf-8')}
function plot(data,tol){if(!data?.length)return '';const max=Math.max(tol,...data.map(q=>Math.abs(q.error)),.01)*1.2,y=v=>100-v/max*75;return '<svg class="novo-graph" viewBox="0 0 600 200" role="img" aria-label="Abweichung in Prozent der Spanne"><rect x="45" y="'+y(tol)+'" width="535" height="'+(y(-tol)-y(tol))+'" fill="#23956b" opacity=".17"/><path d="M45 20V180H580 M45 100H580" stroke="currentColor" fill="none"/><text x="4" y="24" fill="currentColor">'+fmt(max)+'</text><text x="4" y="104" fill="currentColor">0</text><text x="4" y="180" fill="currentColor">'+fmt(-max)+'</text>'+data.map((q,i)=>{const x=65+i*490/Math.max(1,data.length-1);return '<circle cx="'+x+'" cy="'+y(q.error)+'" r="5" fill="'+(q.pass?'#23956b':'#d44b42')+'"/><text x="'+x+'" y="195" text-anchor="middle" fill="currentColor">'+(i+1)+'</text>'}).join('')+'</svg>'}
function checkTable(){return '<div class="novo-table"><table><thead><tr><th>Punkt</th><th>ADC_S</th><th>Referenz ('+esc(s.unit)+')</th>'+(s.t>1?'<th>ADC_T</th>':'')+'<th></th></tr></thead><tbody>'+s.checks.map((q,i)=>'<tr><td>'+(i+1)+'</td>'+['raw','reference',...(s.t>1?['temp']:[])].map(k=>'<td><input aria-label="'+k+' '+(i+1)+'" data-check="'+i+'" data-key="'+k+'" type="number" step="any" value="'+(valid(q[k])?q[k]:'')+'"></td>').join('')+'<td><button data-remove="'+i+'">×</button></td></tr>').join('')+'</tbody></table></div>';}
function verifyContent(){return '<div class="gw-columns">'+tile('Unabhängige Prüfpunkte',number('tolerance','Toleranz (% der Spanne)',s.tol)+checkTable()+actions(btn('checkAdd','Prüfpunkt hinzufügen')+btn('checkRun','Ergebnis prüfen','primary'))+ '<div id="verifyResults">'+(s.results?verifyResults():'')+'</div>')+tile('Was prüfe ich hier?', '<p>Vergleich der Offline-Kennlinie mit unabhängig erfassten Rohwerten. Es werden keine DSP-Register gelesen.</p>'+alert('Prüfergebnis ist keine Hardwarefreigabe.','warn')+actions(btn('checkCsv','CSV exportieren')+btn('checkPrint','PDF / Drucken')),'is-soft')+'</div>'}
function verifyResults(){return alert(s.results.every(q=>q.pass)?'Alle Offline-Prüfpunkte innerhalb der Toleranz.':'Mindestens ein Prüfpunkt ausserhalb der Toleranz.',s.results.every(q=>q.pass)?'success':'error')+plot(s.results,s.tol)+'<div class="novo-table"><table><thead><tr><th>Referenz</th><th>Modell</th><th>Fehler %</th><th>Status</th></tr></thead><tbody>'+s.results.map(q=>'<tr><td>'+fmt(q.reference)+'</td><td>'+fmt(q.actual)+'</td><td>'+fmt(q.error)+'</td><td class="'+(q.pass?'novo-pass':'novo-fail')+'">'+(q.pass?'OK':'NOK')+'</td></tr>').join('')+'</tbody></table></div>'}
function bindVerify(){bindNum('tolerance',v=>{s.tol=v;s.results=null;$('verifyResults').replaceChildren()});root.querySelectorAll('[data-check]').forEach(e=>e.oninput=()=>{s.checks[+e.dataset.check][e.dataset.key]=e.valueAsNumber;s.results=null;$('verifyResults').replaceChildren()});root.querySelectorAll('[data-remove]').forEach(e=>e.onclick=()=>{s.checks.splice(+e.dataset.remove,1);s.results=null;render()});act('checkAdd',()=>{s.checks.push({});s.results=null;render()});act('checkRun',()=>{s.results=null;$('verifyResults').replaceChildren();if(!s.fit)throw Error('Zuerst Kalibrierung berechnen.');if(s.checks.some(q=>s.points.some(c=>q.raw===c.raw&&(s.t===1||q.temp===c.temp))))throw Error('Unabhängige Prüfpunkte verwenden.');s.results=verify(s.fit,s.checks,s.hi-s.lo,s.tol);$('verifyResults').innerHTML=verifyResults()});act('checkCsv',()=>csv(s.results||[],'novosense-verification.csv'));act('checkPrint',()=>window.print())}
function outputContent(){return '<div class="gw-columns">'+tile('Ausgang konfigurieren',fields(number('vdd','Versorgung VDD (V)',s.vdd)+number('s0','S0 · untere Spannung (V)',s.s0)+number('s1','S1 · obere Spannung (V)',s.s1))+actions(btn('scale','Skalierung berechnen','primary')+btn('outRam','In RAM übernehmen','',true))+alert('Nur Sollwertplanung. Ausgangsart und Register sind modellabhängig.','warn'))+tile('Vorschau und Status','<div id="outputResult">'+(s.output?pre('outData',JSON.stringify(s.output,null,2)):'Noch keine Skalierung berechnet.')+'</div>','is-soft')+'</div>'}
function bindOutput(){for(const k of ['vdd','s0','s1'])bindNum(k,v=>{s[k]=v;s.output=null;$('outputResult').replaceChildren()});act('scale',()=>{if(!finite(s.vdd,s.s0,s.s1)||s.vdd<=0||s.s0<0||s.s1<0||s.s0>s.vdd||s.s1>s.vdd||s.s0===s.s1||s.hi<=s.lo)throw Error('Versorgung, Ausgangsgrenzen und Sensorbereich prüfen.');s.output={vdd:s.vdd,s0:s.s0,s1:s.s1,lowerPercent:100*s.s0/s.vdd,upperPercent:100*s.s1/s.vdd,slope:(s.s1-s.s0)/(s.hi-s.lo),intercept:s.s0-(s.s1-s.s0)*s.lo/(s.hi-s.lo)};$('outputResult').textContent=JSON.stringify(s.output,null,2)})}
function homeContent(){return '<div class="gw-columns gw-six">'+tasks.map(([k,icon,title,desc])=>'<button class="gw-choice" data-gw-task="'+k+'"><span class="gw-choice-icon">'+icon+'</span><strong>'+title+'</strong><small>'+desc+'</small></button>').join('')+'</div>'+alert('v0.5.0 · Labortestkandidat. NSA2860X: expliziter RAM-/EEPROM-Testablauf; keine Produktionsfreigabe. Andere Modelle bleiben lesend oder offline.','warn')}
function connection(){const diy=isDiy(selectedAdapter),native=selectedAdapter==='evm',cal32=selectedAdapter==='cal32',connected=!bridge.closed, supported=diy?!!profiles[s.model]:native?nativeAvailable():cal32&&!!navigator.serial,evm=selectedAdapter==='evm',compatible=evm&&['nsa2860(x)','nsa2860x'].includes(s.model);return '<div class="gw-columns">'+tile('USB-Adapter und Chip-Protokoll',fields(select('model','SSC-Modell',models.map(m=>[m.id,m.name]),s.model)+select('adapter','Programmieradapter',Object.entries(adapters).map(([k,v])=>[k,v.name]),selectedAdapter)+(diy?select('address','I²C-Adresse (7 Bit)',(profiles[s.model]?.addresses||[0x6d]).map(a=>[a,'0x'+hex(a)]),chosenAddress):cal32?select('calAddress','32CAL MCU-Adresse',Array.from({length:113},(_,i)=>[128+i,'0x'+hex(128+i)]),calAddress):''))+'<p>'+esc(adapters[selectedAdapter].transport)+'</p>'+(diy?'<p>NOVO-I2C-5 · 115200 Baud. <a href="firmware/novo_i2c/novo_i2c.ino" download>Firmware herunterladen</a></p>':cal32?'<p>Direkte Web-Serial-Versionsdiagnose via USB-RS485. Kein lokaler Dienst erforderlich.</p>':native?'<p><a href="docs/ADAPTERS.md">Lokalen Adapterdienst einrichten</a> · <a href="http://127.0.0.1:8765/">Lokale Web-App öffnen</a></p>':'<p>Das originale NSA2302-Board hat ein separates, noch nicht dokumentiertes Host-Protokoll.</p>')+actions(btn('usb',diy?'USB-Port auswählen':'Originalboard verbinden','primary',!supported||connected)+btn('disconnect','Trennen','',!connected))+alert(device?'Chip antwortet. Part ID: 0x'+hex(device.identity)+' · keine eindeutige UID.':boardInfo?'Board antwortet; Sensor noch nicht erkannt.':diy?(supported?'Experimenteller I²C-Lesetreiber. Verdrahtung prüfen.':'Für dieses Modell fehlt der Treiber.'):native?(nativeAvailable()?'Originalboard-Testbetrieb.':'Originalboard benötigt den lokalen Adapterdienst.'):cal32?'32CAL Board-Diagnose über Web Serial.':'Board-Treiber fehlt.','warn')+(boardInfo?pre('boardInfo',JSON.stringify(boardInfo,null,2)):'')+((native||cal32)&&connected?actions(btn('boardVersion','Board-Version lesen')+(evm?btn('boardEnter','OWI aktivieren (Power-Cycle)','',!compatible)+btn('boardChip','Sensor identifizieren','',!compatible||!!device):'')):'')+(!diy?'<p class="muted small">EVM: Sensor-Lesezugriff experimentell für NSA2860/X. CAL32: nur Board-Version. Keine RAM-/NVM-Schreibbefehle.</p>':''))+tile('Verbindung beheben',actions(btn('hwRead','NVM-Register lesen','',!device)+btn('hwSample','Messwert lesen','',!device)+btn('hwAverage','12 Samples mitteln','',!device)+btn('hwLive',liveTimer?'Live stoppen':'Live starten','',!device)+btn('diagExport','USB-Protokoll exportieren'))+'<p id="hwStatus">Keine neue Messung.</p>'+pre('hwData',latest?JSON.stringify(latest,null,2):'—')+'<div id="livePlot">'+liveGraph()+'</div>'+'<a href="docs/ADAPTERS.md">Adapterprotokolle und Anschluss</a>','is-soft')+'</div>'}

function labCapable(){return device?.model==='nsa2860x'&&isDiy(selectedAdapter)&&!bridge.closed}
function resetLab(){labBase=null;labPlan=null;labChecks=[];labExpected=null;labAttempted=false;labVerified=false;labRamChanged=false;labUnsafe=false;labEdit='{}';try{const p=JSON.parse(localStorage.getItem('novo-pending-eeprom')||'null');if(p){labBase=p.original;labExpected=p.expected;labChecks=p.checks;labAttempted=true;labRamChanged=true;}}catch{labUnsafe=true;}}
function labPanel(){const ok=labCapable(),canWrite=ok&&labBase&&!labAttempted&&!labUnsafe;return tile('NSA2860X · Labor-RAM und EEPROM',alert('Nur entbehrliche Testmuster. Kein OTP, Lock oder Produktionsbetrieb. Originalwerte nach Kaltstart sichern. Generic-Fit niemals als Herstellerkoeffizienten schreiben.','warn')+actions(btn('labBaseline','Kaltstart-Registerabbild sichern','',!ok||labAttempted||labRamChanged||labUnsafe||!!labBase)+btn('labOriginal','Originalwerte JSON exportieren','',!labBase))+ '<p>Erlaubte Felder: '+esc(Object.keys(specs).join(', '))+', diagnostics, alarmEnabled, alarmHigh, clampLowFraction, clampHighFraction.</p><label>Explizite Herstellerkoeffizienten / Parameter (JSON)<textarea id="labEdit" rows="6" spellcheck="false">'+esc(labEdit)+'</textarea></label>'+actions(btn('labPreview','Änderungen und Quantisierung prüfen','primary',!canWrite)+btn('labApply','RAM-Änderungen schreiben','',!canWrite||!labPlan))+pre('labDiff',labPlan?JSON.stringify({quantized:labPlan.quantized,changes:labPlan.changes.map(c=>({...c,address:'0x'+hex(c.address)}))},null,2):'Keine vorbereiteten Änderungen')+ '<h3>Unabhängige DSP-Prüfung</h3><p>RAW_P und RAW_T deaktivieren. Prüfdruck und erwarteten DSP-Code aus unabhängiger Referenz festlegen; mindestens zwei unterschiedliche Sollwerte. Keine automatische Umrechnung des generischen Fits.</p>'+fields(number('labTarget','Erwarteter PDATA-Code (Digits)',null)+number('labTolerance','Toleranz (Digits)',1000))+actions(btn('labCheck','12 frische DSP-Werte prüfen','',!canWrite)+btn('labClear','Prüfpunkte löschen','',!canWrite))+pre('labChecks',JSON.stringify(labChecks,null,2))+ '<h3>EEPROM-Testprogrammierung</h3>'+alert(labVerified?'Kaltstart-Registervergleich und CRC-Status erfolgreich.':labUnsafe?'RAM-Schreibstatus unbekannt. Kaltstart und neue Verbindung erforderlich.':labAttempted?'Programmierversuch erfolgt. Nicht erneut schreiben. Sensor aus- und wieder einschalten, dann Readback prüfen.':'Gesperrt bis Originalabbild, RAM-Änderung und zwei bestandene unabhängige Prüfungen vorliegen.','warn')+actions(btn('labProgram','EEPROM am Testchip programmieren','danger',!canWrite||!labRamChanged||labChecks.length<2||!labChecks.every(x=>x.pass)||new Set(labChecks.map(x=>x.expected)).size<2)+btn('labCold','Kaltstart-Readback vergleichen','',!ok||!labExpected||labVerified)+btn('labReport','Laborprotokoll exportieren','',!labBase)),'is-soft')}
function liveGraph(){const rows=historyRows.slice(-240).map((v,i)=>({i,y:v.pressureRaw??v.pressureCal})).filter(v=>Number.isFinite(v.y));if(rows.length<2)return '<p>Mindestens zwei Live-Werte nötig.</p>';const min=Math.min(...rows.map(v=>v.y)),max=Math.max(...rows.map(v=>v.y)),span=max-min||1;return '<svg class="novo-graph" viewBox="0 0 600 180" role="img" aria-label="ADC/DSP Live-Verlauf"><path d="M55 20V150H580" fill="none" stroke="currentColor"/><text x="4" y="22" font-size="10" fill="currentColor">'+fmt(max)+'</text><text x="4" y="150" font-size="10" fill="currentColor">'+fmt(min)+'</text><polyline points="'+rows.map((v,i)=>(55+525*i/(rows.length-1))+','+(150-130*(v.y-min)/span)).join(' ')+'" fill="none" stroke="#16856c" stroke-width="2"/><text x="55" y="170" font-size="10" fill="currentColor">letzte '+rows.length+' Werte</text></svg>'}
async function patchRam(p){if(!labCapable()||labAttempted||labUnsafe)throw Error('RAM-Test nicht verfügbar');const current=bytesOf(await device.snapshot());if(!equalBytes(current,p.before))throw Error('Register seit Vorschau verändert – neu vorbereiten');labChecks=[];labRamChanged=true;for(const g of patchGroups(p.before,p.target)){await bridge.request('W 6D '+hex(g.r)+' '+g.old.length+' '+hexBytes(g.old)+' '+hexBytes(g.next));}const after=await device.snapshot();if(!equalBytes(bytesOf(after),p.target))throw Error('RAM-Rücklesefehler, Kaltstart erforderlich');return after;}
function bindLab(){on('labEdit','input',e=>{labEdit=e.target.value;labPlan=null;if($('labApply'))$('labApply').disabled=true;if($('labDiff'))$('labDiff').textContent='Änderungen erneut prüfen.'});act('labBaseline',()=>runHardware(async()=>{stopLive();if(!confirm('Ist dies ein entbehrlicher NSA2860X-Testchip, der gerade vollständig aus- und wieder eingeschaltet wurde? Keine vorherigen RAM-Änderungen.'))return;const b=await device.snapshot();if((b.status&0xfe)!==2||b.coefficients.locked)throw Error('Statusfehler oder EEPROM gesperrt');labBase=b;labPlan=null;labChecks=[];snapshot=b;render();message('Originalabbild gesichert. Kaltstart vom Bediener bestätigt.','success')}));act('labOriginal',()=>download('nsa2860x-original-shadow.json',JSON.stringify(labBase,null,2)));act('labPreview',()=>runHardware(async()=>{stopLive();labPlan=planEdit(await device.snapshot(),JSON.parse(labEdit));render()}));act('labApply',()=>runHardware(async()=>{if(!labPlan?.changes.length)throw Error('Keine Änderungen');if(!confirm('Nur am entbehrlichen Testchip: diese RAM-Änderungen schreiben? Analogausgang kann sich ändern.'))return;stopLive();const p=labPlan;labPlan=null;try{snapshot=await patchRam(p)}catch(e){labUnsafe=true;render();throw e}render();message('RAM-Register vollständig rückgelesen.','success')}));act('labCheck',()=>runHardware(async()=>{stopLive();const expected=$('labTarget').valueAsNumber,tolerance=$('labTolerance').valueAsNumber;const before=bytesOf(await device.snapshot());if(before[0xa5-0xa1]&1||before[0xa6-0xa1]&1)throw Error('RAW_P und RAW_T zuerst deaktivieren');const v=await device.collect(12);const after=bytesOf(await device.snapshot());if(!equalBytes(before,after))throw Error('Register während Messung verändert');const check=checkDsp(v.pressureCal,expected,tolerance);labChecks.push({...check,hash:hashBytes(after),samples:v.samples,time:new Date().toISOString()});render()}));act('labClear',()=>{labChecks=[];render()});act('labProgram',()=>runHardware(async()=>{stopLive();const b=await device.snapshot(),bytes=bytesOf(b),digest=hashBytes(bytes);if(!labBase||!labRamChanged||labAttempted||labUnsafe||b.coefficients.locked||(b.status&0xfe)!==2||bytes[0xa5-0xa1]&1||bytes[0xa6-0xa1]&1||labChecks.length<2||new Set(labChecks.map(x=>x.expected)).size<2||!labChecks.every(x=>x.pass&&x.hash===digest))throw Error('Sicherheitsfreigaben fehlen oder Register verändert');if(!confirm('Testchip endgültig programmieren? Originalabbild exportiert, Analogausgang separat gemessen, Versorgung 3–5.5 V stabil und Chiptemperatur im zulässigen Bereich? Keine Wiederholung bei Kommunikationsfehler.'))return;if(prompt('Zur Bestätigung EEPROM TEST eingeben')!=='EEPROM TEST')return;localStorage.setItem('novo-pending-eeprom',JSON.stringify({original:labBase,expected:bytes,checks:labChecks,createdAt:new Date().toISOString()}));labExpected=bytes;labAttempted=true;labPlan=null;try{await bridge.request('P 6D '+digest.toString(16).padStart(8,'0'));render();message('Programmierbefehl abgeschlossen. Sensor manuell kaltstarten, dann Registervergleich.','warn')}catch(e){render();throw Error('Programmierstatus unbekannt. Nicht erneut schreiben. Kaltstart und Readback prüfen. '+e.message)}}));act('labCold',()=>runHardware(async()=>{if(!confirm('Sensorversorgung tatsächlich aus- und wieder eingeschaltet?'))return;const b=await device.snapshot();snapshot=b;labVerified=equalBytes(bytesOf(b),labExpected)&&(b.status&0xfe)===2;if(labVerified)localStorage.removeItem('novo-pending-eeprom');render();message(labVerified?'Kaltstart-Readback stimmt überein, CRC-Status OK.':'Kaltstart-Readback oder Status fehlerhaft. Nicht erneut schreiben.',labVerified?'success':'error')}));act('labReport',()=>download('nsa2860x-laborbericht.json',JSON.stringify({model:s.model,adapter:selectedAdapter,original:labBase,checks:labChecks,expected:labExpected,attempted:labAttempted,verified:labVerified,physicalColdStartOperatorConfirmed:labVerified},null,2)));}

function registerTable(){if(!snapshot)return '<p>Keine ausgelesenen Register.</p>';return '<div class="novo-table"><table><thead><tr><th>Adresse</th><th>Register</th><th>Hex</th><th>Dezimal</th></tr></thead><tbody>'+snapshot.registers.map(r=>'<tr><td>0x'+hex(r.address)+'</td><td>'+esc(r.name)+'</td><td>0x'+hex(r.value)+'</td><td>'+r.value+'</td></tr>').join('')+'</tbody></table></div>'+alert(snapshot.kind+' · physischer NVM-Inhalt nicht separat verifiziert. STATUS 0x'+hex(snapshot.status))+(snapshot.coefficients?'<h3>Dekodierte Kalibrierkoeffizienten</h3>'+pre('decodedCoefficients',JSON.stringify(snapshot.coefficients,null,2)):'');}
function content(){if(s.task==='home')return homeContent();if(s.task==='connection')return connection();if(s.task==='verification')return verifyContent();if(s.task==='output')return outputContent();if(s.task==='alarms')return tile('Alarme & Fehler (optional)',alert('Status und Alarmregister nur lesend prüfen. Bestehende Register bleiben unverändert.','warn')+actions(btn('alarmRead','Alarme und Status auslesen','primary',!device||device.model!=='nsa2860x')+btn('alarmWrite','In RAM übernehmen','',true))+pre('alarmResult','—'));if(s.task==='bridge')return '<div class="gw-columns">'+tile('Sensorbrücke analysieren',fields(number('bridgeV','Brückenspeisung (V)',5)+number('bridgeLo','Signal bei unterer Referenz (mV)',0)+number('bridgeHi','Signal bei oberer Referenz (mV)',15)+number('bridgeTemp1','Temperatur 1 (°C)',25)+number('bridgeTemp2','Temperatur 2 (°C)',80)+number('bridgeLo2','Nullpunkt T2 (mV)',0)+number('bridgeHi2','Endwert T2 (mV)',15))+actions(btn('bridgeCalc','Berechnen','primary')))+tile('Formeln und Ergebnisse','<p class="novo-formula">Nullpunkt = Umin / Vexc<br>Spanne = (Umax − Umin) / Vexc<br>TK0 = ΔNullpunkt / Spanne / ΔT<br>TKE = ΔSpanne / Spanne / ΔT</p>'+pre('bridgeResult','—')+'<p>Keine Rekonstruktion aus Chip-NVM; manuelle Brückenmessung.</p>','is-soft')+'</div>';
if(s.task==='inspect')return '<div class="gw-columns">'+tile('EEPROM / Diagnose','<p>Binärdatei mit extern ausgelesenen Rohdaten importieren. Keine Registerinterpretation ohne bestätigte Registermap.</p><input id="dump" type="file" accept=".bin,.hex,.dat,.txt,.json">'+pre('dumpResult',s.diag?.display||'—')+'<div id="nvmRegisters">'+registerTable()+'</div>'+actions(btn('dumpRead','Chip auslesen','primary',!device)+btn('dumpExport','Diagnose exportieren')+btn('nvmBackup','Registerabbild JSON sichern','',!snapshot)))+(s.model==='nsa2860x'?labPanel():tile('Sicherheitsstatus',alert('Dateiimport oder echtes Registerauslesen über I²C. Kein permanentes Schreiben.','warn'),'is-soft'))+'</div>';
if(s.task==='testlog')return tile('Test / Logging',fields(number('logRaw','ADC_S (Digits)',null)+number('logTemp','ADC_T (Digits)',null)+number('logRef','Referenz',null)+'<label>Notiz<input id="logNote" maxlength="250"></label>')+actions(btn('logAdd','Messwert erfassen','primary')+btn('hwLog','Chipmessung erfassen','',!device)+btn('logLive',recording?'Logging stoppen':'Logging starten','',!device)+btn('logCsv','CSV exportieren')+btn('logSave','Archivieren'))+'<div class="novo-table"><table><thead><tr><th>Zeit</th><th>ADC_S</th><th>ADC_T</th><th>Referenz</th><th>Notiz</th></tr></thead><tbody>'+s.log.map(q=>'<tr><td>'+esc(q.time)+'</td><td>'+fmt(q.raw)+'</td><td>'+fmt(q.temp)+'</td><td>'+fmt(q.reference)+'</td><td>'+esc(q.note)+'</td></tr>').join('')+'</tbody></table></div>'+'<p>Messwerte: <strong id="logCount">'+s.log.length+'</strong> · Live-Logging ca. 350 ms, bis 10’000 Werte</p><div id="livePlot">'+liveGraph()+'</div>'+alert('Nur frische Chipwerte; CSV vor Modellwechsel exportieren.'));
if(s.task==='archive')return tile('Lokales Kalibrierarchiv','<label>Suchen<input id="archiveSearch" placeholder="Modell / Datum / Typ"></label><div id="archiveList"></div><p class="muted small">Browserlokale Speicherung; JSON-Export als dauerhafte Sicherung.</p>');
switch(s.step){
case 1:return '<div class="gw-preset-grid">'+[['quick','Schnell','0–100 % · 2 Druckpunkte, ohne Temperaturkorrektur.'],['tk0','TK0 · 3 Punkte','2 Druckpunkte bei T1, Nullpunkt bei T2; Offline-Modell.'],['thermal','Mit Temperatur','0–100 % · 2 Druckpunkte × 3 Temperaturstufen.'],['custom','Individuell','3 Druckpunkte × 2 Temperaturstufen; anpassbar.']].map(([k,a,b])=>'<button class="gw-preset" data-preset="'+k+'"><strong>'+a+'</strong><small>'+b+'</small></button>').join('')+'</div>'+tile('Deinen Messablauf festlegen',fields(select('p','Druckpunkte',[2,3,4],s.p)+select('t','Temperaturbedingungen',[[1,'1 · keine Temperaturkorrektur'],[2,'2 · linear'],[3,'3 · quadratisch']],s.t),'gw-3')+'<div class="gw-fieldnote">Vollständige Druck-Temperatur-Matrix für ein allgemeines Offline-Polynom. Keine Herstellerkoeffizienten.</div>','is-soft')+'<div class="gw-summary"><strong>'+(s.tk0?3:s.p*s.t)+' Messpunkte</strong> · Druckordnung '+(s.p-1)+' · Temperaturordnung '+(s.t-1)+'</div>';
case 2:return '<div class="gw-columns gw-setup-grid">'+tile('Druckbereich und Messung',fields(select('model','SSC-Modell',models.map(m=>[m.id,m.name]),s.model)+select('unit','Einheit',['%','bar','mbar','psi','kPa','MPa'],s.unit)+number('lo','Unterer Referenzwert',s.lo)+number('hi','Oberer Referenzwert',s.hi)))+tile('Temperatur und DSP',fields(s.temps.slice(0,s.t).map((v,i)=>number('temp'+i,'Temperatur '+(i+1)+' (°C)',v)).join(''))+'<p>Temperatur-Sollwerte dienen der Messplanung. Für den Fit sind Temperatur-Rohwerte erforderlich.</p>')+'</div>'+alert('Änderungen an Messplan oder Sensorbereich verwerfen die bisherigen Messpunkte.');
case 3:return '<div class="gw-columns gw-afe-layout">'+tile('Verstärkung und Offset',fields(number('afeLow','ADC_S bei unterem Druck',s.afe.low)+number('afeHigh','ADC_S bei oberem Druck',s.afe.high)+number('afeBits','Signed ADC-Bits (manuell)',s.afe.bits)+number('afeTarget','Zielaussteuerung (%)',s.afe.target))+ (device?.model==='nsa2860x'?fields(select('chipGain','PGA Gain',gains2860,s.afe.chipGain||1)+'<label class="novo-check"><input id="chipSwap" type="checkbox" '+(s.afe.chipSwap?'checked':'')+'> Polarität invertieren</label><label class="novo-check"><input id="chipRawP" type="checkbox" '+(s.afe.chipRawP?'checked':'')+'> RAW_P</label><label class="novo-check"><input id="chipRawT" type="checkbox" '+(s.afe.chipRawT?'checked':'')+'> RAW_T</label>'):'')+actions(btn('afeCalc','Aussteuerung berechnen','primary')+btn('afeSuggest','Gain vorschlagen','',device?.model!=='nsa2860x')+btn('afeRam','In RAM übernehmen','',device?.model!=='nsa2860x'||!isDiy(selectedAdapter))+btn('afeRead','AFE auslesen','',device?.model!=='nsa2860x'))+'<div class="gw-fieldnote">Theoretische Aussteuerung; NSA2860X zusätzlich mit temporärer AFE-Konfiguration.</div>')+tile('ADC_S · Aussteuerung','<div class="gw-afe-current"><strong id="afeCurrent">—</strong><span>Digits</span></div>'+pre('afeResult','Noch keine Berechnung')+alert('Live-Werte in der Kopfzeile, sobald ein unterstützter Chip verbunden ist.'))+'</div>';
case 4:{const q=s.points[s.selected];return '<div class="gw-points-layout"><div class="gw-point-nav">'+s.points.map((p,i)=>'<button data-point="'+i+'" class="'+(i===s.selected?'gw-selected ':'')+(valid(p.raw)&&valid(p.reference)&&(s.t===1||valid(p.temp))?'gw-done':'')+'">'+(i+1)+' · '+fmt(p.reference)+' '+esc(s.unit)+' · '+fmt(p.targetTemp)+' °C</button>').join('')+'</div>'+tile('Messpunkt '+(s.selected+1)+' / '+s.points.length,'<div class="gw-summary gw-next-point">Sollwert '+fmt(q.reference)+' '+esc(s.unit)+' · '+fmt(q.targetTemp)+' °C</div>'+fields(number('pointRaw','ADC_S · Rohwert',q.raw)+number('pointRef','Tatsächliche Referenz',q.reference)+(s.t>1?number('pointTemp','ADC_T · Rohwert',q.temp):''))+actions(btn('capture','Messpunkt übernehmen','primary')+btn('hwCapture','ADC vom Chip übernehmen','',!device)+btn('synthetic','Beispieldaten laden'))+'<p class="muted small">Quelle: '+(s.source==='synthetic'?'synthetisch / gemischt':'manuelle Eingabe')+'</p>')+'</div>'+alert('Druck und Temperatur müssen am Prüfplatz eingestellt werden. Chip-Rohwerte können bei unterstütztem Modell übernommen werden.');}
case 5:return '<div class="gw-columns">'+tile('Polynom und DSP-Ziel','<p class="novo-formula">f(x,t) = Σ cᵢⱼ · xⁱ · tʲ (normierte Rohwerte)</p>'+actions(btn('compute','Koeffizienten berechnen','primary')+btn('fitRam','Ins Chip-RAM übertragen','',true))+pre('fitResult',s.fit?JSON.stringify(s.fit,null,2):'Noch keine Berechnung')+(s.model==='nsa2300'&&$('expertMode').checked?'<h3>NSA2300 · 2P/1T</h3>'+fields(number('nativeX1','CNT sense 1',null)+number('nativeX2','CNT sense 2',null)+number('nativeY1','P1',0)+number('nativeY2','P2',1)+number('nativeP0','P0',0))+actions(btn('nativeCalc','CNT_off / S0 berechnen'))+pre('nativeResult','—'):''))+tile('Sicherer Ablauf','<p>1. Messpunkte erfassen.</p><p>2. Modell berechnen und Residuen kontrollieren.</p><p>3. Unabhängige Prüfpunkte aufnehmen.</p>'+alert('Allgemeines Polynom ist keine NOVOSENSE-Registerkodierung.','warn'),'is-soft')+'</div>';
case 6:return verifyContent();case 7:return outputContent();case 8:return tile('Alarme & Fehler (optional)',alert('Kein validierter Alarm-Schreibtreiber. Dieser Schritt kann ohne Änderungen übersprungen werden.','warn')+actions(btn('alarmSkip','Ohne Alarmänderung weiter','primary')));
case 9:return '<div class="gw-columns">'+tile('Änderungen prüfen und bestätigen',alert('Generische Offline-Kennlinie nicht programmierbar. NSA2860X: separater Laborablauf für explizite Herstellerwerte.','warn')+actions(btn('nvmRead','NVM-Register lesen','',!device)+btn('nvmBackup','Registerabbild sichern','',!snapshot)+btn('nvmWrite','NVM programmieren','danger',true)+btn('export','Offline-Bericht exportieren'))+'<div id="nvmRegisters">'+registerTable()+'</div>')+(s.model==='nsa2860x'?labPanel():tile('Wichtig vor dem NVM-Schreiben','<p>Chip-ID, Registermap, Prüfsummen, Readback und Schreibschutz sind zuerst je Modell zu validieren.</p>','is-warning'))+'</div>';
case 10:return '<div class="gw-columns">'+tile('Abgleich und Freigabe',alert(s.fit?'Offline-Kennlinie berechnet. Generischer Fit wurde nicht in den Chip geschrieben.':'Keine Kennlinie berechnet.',s.fit?'':'warn')+actions(btn('export','JSON-Bericht exportieren','primary')+btn('finishCsv','CSV-Prüfwerte')+btn('finishPrint','PDF / Drucken')+btn('finishSave','Archivieren')))+tile('Ergebnis',pre('finishResult',JSON.stringify(report(),null,2)),'is-soft')+'</div>';default:return ''}}
function stopLive(){if(liveTimer)clearInterval(liveTimer);liveTimer=null;recording=false;}
function updateHeader(){ $('status').textContent=device?'Chip antwortet · Testbetrieb':boardInfo?'Board verbunden':'Nicht verbunden';$('statusDot').classList.toggle('active',!!boardInfo||!!device);$('liveState').textContent=latest?'Letzte Chipmessung':'Keine Live-Messung';$('liveAdcS').textContent=fmt(latest?.pressureRaw);$('liveAdcT').textContent=fmt(latest?.tempRaw);$('liveDspS').textContent=fmt(latest?.pressureCal);$('liveTempC').textContent=fmt(latest?.tempC);$('liveLastRead').textContent=latest?new Date(latest.time).toLocaleTimeString('de-CH'):'—';}
async function runHardware(fn){if(hardwareBusy)return;hardwareBusy=true;root.inert=true;try{await fn()}catch(e){stopLive();if(bridge.closed){device=null;boardInfo=null;latest=null;snapshot=null;resetLab();historyRows=[];render();updateHeader();}message(e.message,'error')}finally{hardwareBusy=false;root.inert=false;}}
async function getSample(trigger){if(!device||bridge.closed)throw Error('Zuerst verbinden');let v=trigger&&device.model==='nsa2300'?await device.measurePressure():await device.sample();if(!v){if($('hwStatus'))$('hwStatus').textContent='DRDY nicht gesetzt – kein neuer Wert';return null;}latest={...v,time:new Date().toISOString()};historyRows.push(latest);if(historyRows.length>240)historyRows.shift();if(recording){if(s.log.length>=10000){stopLive();message('Logging-Limit erreicht. CSV exportieren.','warn')}else{s.log.push({time:latest.time,raw:v.pressureRaw,temp:v.tempRaw,pressureCal:v.pressureCal,tempC:v.tempC,reference:logMeta.reference,note:logMeta.note,source:'chip'});if($('logCount'))$('logCount').textContent=String(s.log.length);}}if($('livePlot'))$('livePlot').innerHTML=liveGraph();updateHeader();if($('hwData'))$('hwData').textContent=JSON.stringify(latest,null,2);if($('hwStatus'))$('hwStatus').textContent='Neuer Messwert';return latest;}
function render(){document.documentElement.classList.toggle('guided-task-open',s.task!=='home'||classic);$('guidedLaunchTop').textContent=classic?'◇ Geführt':'◇ Klassisch';$('guidedLaunchTop').setAttribute('aria-pressed',String(classic));const cal=s.task==='calibration',homeMode=s.task==='home';const title=cal?steps[s.step][1]:homeMode?steps[0][1]:s.task==='connection'?'Verbindung & Diagnose':tasks.find(x=>x[0]===s.task)?.[2]||'';const desc=cal?steps[s.step][2]:homeMode?steps[0][2]:s.task==='connection'?'Programmieradapter und SSC auswählen.':tasks.find(x=>x[0]===s.task)?.[3]||'';root.innerHTML='<div class="gw-shell '+(classic?'novo-classic':homeMode?'novo-home':'')+'"><aside class="gw-sidebar"><div class="gw-backlogo"><span>◆</span> NOVOSENSE · '+(classic?'Klassisch':'Geführter Abgleich')+'</div><nav class="gw-sideitems">'+steps.map((v,i)=>'<button type="button" class="gw-sideitem '+(cal&&i===s.step?'is-active':cal&&i<s.step?'is-done':'')+'" data-step="'+i+'"><span class="gw-no">'+(i+1)+'</span><span>'+v[0]+'</span></button>').join('')+(classic?tasks.filter(x=>x[0]!=='calibration').map(([k,icon,title])=>'<button type="button" class="gw-sideitem '+(s.task===k?'is-active':'')+'" data-gw-task="'+k+'"><span class="gw-no">'+icon+'</span><span>'+title+'</span></button>').join(''):'')+'</nav><div class="gw-sidebar-footer">Die Ansicht kann jederzeit gewechselt werden.<div>Laborversion · keine Hardwarefreigabe</div></div></aside><main class="gw-main"><div class="gw-topline"><span class="gw-kicker">'+(cal?'Schritt '+(s.step+1):homeMode?'Aufgabenauswahl':'NOVOSENSE')+'</span><div class="gw-connection-top-actions"><span class="gw-chipstatus is-offline">'+(device?'Chip antwortet · Testbetrieb':boardInfo?'Board verbunden · kein Chip':'Nicht verbunden · Offline')+'</span>'+btn('gwConnectionToggle','Verbindung & Diagnose','gw-connection-link')+'</div></div><div class="gw-progressbar"><span style="width:'+(cal?s.step*10:0)+'%"></span></div><div class="gw-heading-row"><div><h2 class="gw-title">'+esc(title)+'</h2><p class="gw-desc">'+esc(desc)+'</p></div></div><div class="gw-page">'+content()+'</div><div id="gwMessage" class="gw-alert" role="status" hidden></div><footer class="gw-footer"><small>NOVOSENSE · Kalibrierassistent</small><div class="gw-actions">'+(homeMode?btn('viewToggle',classic?'Geführt':'Klassisch'):btn('gwTasks','Zur Aufgabenübersicht')+(cal?btn('gwPrevious','Zurück')+btn('gwNext',s.step===10?'Fertig':'Weiter','primary'):''))+'</div></footer></main></div>';root.querySelectorAll('[data-gw-task]').forEach(e=>e.onclick=()=>task(e.dataset.gwTask));root.querySelectorAll('[data-step]').forEach(e=>e.onclick=()=>go(+e.dataset.step));act('viewToggle',toggleView);act('gwTasks',home);act('gwConnectionToggle',()=>task('connection'));act('gwPrevious',()=>go(s.step-1));act('gwNext',()=>s.step===10?home():go(s.step+1));bindSel('model',setModel);bindSel('address',v=>chosenAddress=+v);bindSel('calAddress',v=>calAddress=+v);bindSel('adapter',v=>{if(!bridge.closed)return;selectedAdapter=v;render()});act('usb',()=>runHardware(async()=>{if(!bridge.closed)throw Error('Adapter zuerst trennen');if(isDiy(selectedAdapter)){if(!navigator.serial)throw Error('Web Serial benötigt Chrome/Edge über HTTPS.');if(!profiles[s.model])throw Error('Treiber fehlt.');if(!confirm('Nur einen korrekt verdrahteten, eindeutig identifizierten Testchip anschliessen. Modell und Logikpegel geprüft?'))return;const port=await navigator.serial.requestPort();bridge=new Bridge();await bridge.connect(port,adapters[selectedAdapter].firmware);try{const d=new Device(bridge,s.model,chosenAddress);await d.identify();device=d;resetLab();boardInfo={board:bridge.info,protocol:'NOVO-I2C-5'};}catch(e){await bridge.close();throw e}}else if(selectedAdapter==='cal32'){if(!navigator.serial)throw Error('Chrome/Edge mit Web Serial erforderlich');const port=await navigator.serial.requestPort();bridge=new Cal32Bridge(calAddress);boardInfo=await bridge.connect(port);}else{bridge=new NativeBridge(selectedAdapter);boardInfo=await bridge.connect();}latest=null;snapshot=null;render();updateHeader();message(device?'I²C-Chip antwortet. Modell manuell gewählt.':'Originalboard antwortet. Sensor separat identifizieren.','success')}));act('disconnect',()=>runHardware(async()=>{stopLive();try{await bridge.close()}finally{device=null;boardInfo=null;latest=null;snapshot=null;render();updateHeader()}}));act('boardVersion',()=>runHardware(async()=>{boardInfo=await bridge.version();render();message('Board-Version gelesen.','success')}));act('boardEnter',()=>runHardware(async()=>{if(!confirm('OWI am entbehrlichen Test-DUT aktivieren? Das Originalboard schaltet die Sensorversorgung kurz aus und ein. Ausgangstyp und Verdrahtung müssen stimmen.'))return;stopLive();device=null;latest=null;snapshot=null;resetPoints();updateHeader();await bridge.enter();render();message('OWI-Befehl bestätigt. Sensor jetzt identifizieren.','success')}));act('boardChip',()=>runHardware(async()=>{if(selectedAdapter!=='evm'||!['nsa2860(x)','nsa2860x'].includes(s.model))throw Error('Kein freigegebener Sensor-Lesepfad');const d=new Device(bridge,s.model,0x6d);await d.identify();device=d;resetLab();latest=null;snapshot=null;render();updateHeader();message('OWI-Chip antwortet. Part ID ist keine UID.','success')}));for(const id of ['hwRead','dumpRead','nvmRead'])act(id,()=>runHardware(async()=>{if(!device)throw Error('Zuerst verbinden');stopLive();snapshot=await device.snapshot();render();message(snapshot.registers.length+' Register gelesen. Kein NVM-Schreibvorgang.','success')}));act('nvmBackup',()=>{if(!snapshot)throw Error('Zuerst Register lesen');download('novosense-registers.json',JSON.stringify(snapshot,null,2))});act('alarmRead',()=>runHardware(async()=>{stopLive();const r=await device.snapshot();snapshot=r;$('alarmResult').textContent=JSON.stringify({status:r.status,decoded:status2860(r.status),alarm:r.coefficients?.alarm,locked:r.coefficients?.locked},null,2)}));if(s.task==='connection'){if($('address'))$('address').disabled=!bridge.closed;if($('adapter'))$('adapter').disabled=!bridge.closed;if($('calAddress'))$('calAddress').disabled=!bridge.closed;if($('model'))$('model').disabled=!bridge.closed;act('diagExport',()=>runHardware(async()=>{if(bridge instanceof NativeBridge&&!bridge.closed)await bridge.fetchLog();download('novosense-usb-log.json',JSON.stringify({model:s.model,adapter:selectedAdapter,boardInfo,connected:!!device,log:bridge.log,snapshot},null,2))}));act('hwSample',()=>runHardware(async()=>{await getSample(true)}));act('hwAverage',()=>runHardware(async()=>{stopLive();const v=await device.collect(12);latest={...v,time:new Date().toISOString()};updateHeader();$('hwData').textContent=JSON.stringify(latest,null,2);$('hwStatus').textContent='12 frische Samples gemittelt';}));act('hwLive',()=>{if(liveTimer){stopLive();render()}else{liveTimer=setInterval(()=>{if(!hardwareBusy)void runHardware(()=>getSample(false))},350);render()}});return}

if(s.task==='verification'){bindVerify();return}if(s.task==='output'){bindOutput();return}
if(s.task==='bridge'){act('bridgeCalc',()=>{const [v,a,b,t1,t2,c,d]=['bridgeV','bridgeLo','bridgeHi','bridgeTemp1','bridgeTemp2','bridgeLo2','bridgeHi2'].map(k=>$(k).valueAsNumber);if(!finite(v,a,b,t1,t2,c,d)||v<=0||a===b||t1===t2)throw Error('Versorgung, Spanne und Temperaturdifferenz prüfen.');const span=(b-a)/v;s.bridge={offset_mV_V:a/v,span_mV_V:span,TK0_percent_span_per_K:100*(c-a)/(b-a)/(t2-t1),TKE_percent_per_K:100*((d-c)-(b-a))/(b-a)/(t2-t1)};$('bridgeResult').textContent=JSON.stringify(s.bridge,null,2)});return}
if(s.task==='inspect'){bindLab();on('dump','change',async e=>{const f=e.target.files[0];if(!f)return;if(f.size>1024*1024){message('Datei maximal 1 MiB.','error');return}const bytes=new Uint8Array(await f.arrayBuffer());const display=Array.from({length:Math.ceil(Math.min(bytes.length,4096)/16)},(_,i)=>i.toString(16).padStart(4,'0')+'  '+Array.from(bytes.slice(i*16,i*16+16),x=>x.toString(16).padStart(2,'0')).join(' ')).join('\n');s.diag={name:f.name,size:bytes.length,display};if($('dumpResult'))$('dumpResult').textContent=display+(bytes.length>4096?'\n… Vorschau begrenzt':'')});act('dumpExport',()=>{if(!s.diag)throw Error('Zuerst Datei importieren.');download('novosense-dump-preview.json',JSON.stringify(s.diag,null,2))});return}
if(s.task==='testlog'){act('logLive',()=>{if(recording){stopLive();render();return;}stopLive();recording=true;logMeta={reference:$('logRef').valueAsNumber,note:$('logNote').value};liveTimer=setInterval(()=>{if(!hardwareBusy)void runHardware(()=>getSample(true))},350);render()});act('hwLog',()=>runHardware(async()=>{const v=await getSample(true);if(!v)throw Error('Keine neue Messung');s.log.push({time:new Date().toISOString(),raw:v.pressureRaw,temp:v.tempRaw,pressureCal:v.pressureCal,tempC:v.tempC,reference:$('logRef')?.valueAsNumber,note:$('logNote')?.value||''});render()}));act('logAdd',()=>{const raw=$('logRaw').valueAsNumber;if(!valid(raw))throw Error('ADC_S eingeben.');s.log.push({time:new Date().toISOString(),raw,temp:$('logTemp').valueAsNumber,reference:$('logRef').valueAsNumber,note:$('logNote').value});render()});act('logCsv',()=>csv(s.log,'novosense-log.csv'));act('logSave',()=>{if(!s.log.length)throw Error('Keine Messwerte.');archiveSave({type:'logging',model:s.model,createdAt:new Date().toISOString(),mode:'offline',log:s.log})});return}
if(s.task==='archive'){const a=archiveRead(),show=()=>{$('archiveList').innerHTML=a.map((r,i)=>({r,i})).filter(({r})=>JSON.stringify([r.model,r.createdAt,r.type]).toLowerCase().includes($('archiveSearch').value.toLowerCase())).map(({r,i})=>'<div class="novo-archive-item"><span>'+esc(r.model)+' · '+esc(r.createdAt)+' · '+esc(r.type||'Kalibrierung')+'</span><button data-archive="'+i+'">JSON exportieren</button></div>').join('')||'<p>Keine Einträge.</p>';$('archiveList').querySelectorAll('[data-archive]').forEach(e=>e.onclick=()=>download('novosense-archive.json',JSON.stringify(a[+e.dataset.archive],null,2)))};on('archiveSearch','input',show);show();return}
if(!cal)return;
if(s.step===1){root.querySelectorAll('[data-preset]').forEach(e=>e.onclick=()=>{const [p,t]=({quick:[2,1],tk0:[2,2],thermal:[2,3],custom:[3,2]})[e.dataset.preset];s.p=p;s.t=t;s.tk0=e.dataset.preset==='tk0';resetPoints();go(2)});for(const k of ['p','t'])bindSel(k,v=>{s[k]=+v;s.tk0=false;resetPoints();render()})}
if(s.step===2){bindSel('unit',v=>{s.unit=v;resetPoints()});for(const k of ['lo','hi'])bindNum(k,v=>{s[k]=v;resetPoints()});for(let i=0;i<s.t;i++)bindNum('temp'+i,v=>{s.temps[i]=v;resetPoints()})}
if(s.step===3){act('afeRead',()=>runHardware(async()=>{stopLive();const a=await device.afeState();Object.assign(s.afe,{chipGain:a.gain,chipSwap:a.swap,chipRawP:a.rawP,chipRawT:a.rawT});render();$('afeResult').textContent=JSON.stringify(a,null,2)}));act('afeRam',()=>runHardware(async()=>{if(!confirm('Nur am entbehrlichen Testchip: AFE und RAW-Modus temporär ändern? Der Analogausgang kann sich ändern. Kein EEPROM-Schreiben. Bestehende Messpunkte werden gelöscht.'))return;stopLive();if(labAttempted||labUnsafe)throw Error('EEPROM-/RAM-Teststatus offen – zuerst Kaltstart prüfen');labChecks=[];labPlan=null;labRamChanged=true;resetPoints();snapshot=null;latest=null;historyRows=[];updateHeader();let result;try{result=await device.applyAfe(+$('chipGain').value,$('chipSwap').checked,$('chipRawP').checked,$('chipRawT').checked)}catch(e){labUnsafe=true;throw e;}Object.assign(s.afe,{chipGain:result.after.gain,chipSwap:result.after.swap,chipRawP:result.after.rawP,chipRawT:result.after.rawT});resetPoints();snapshot=null;latest=null;updateHeader();render();$('afeResult').textContent=JSON.stringify(result,null,2);message('AFE-RAM rückgelesen. Keine EEPROM-Programmierung.','success')}));for(const [id,k] of [['afeLow','low'],['afeHigh','high'],['afeBits','bits'],['afeTarget','target']])bindNum(id,v=>{s.afe[k]=v;$('afeResult').textContent='Erneut berechnen.'});act('afeSuggest',()=>runHardware(async()=>{stopLive();const cur=await device.afeState();const v=gainSuggestion(s.afe.low,s.afe.high,cur.gain,gains2860,s.afe.target/100);s.afe.chipGain=v.gain;$('chipGain').value=String(v.gain);$('afeResult').textContent=JSON.stringify(v,null,2)}));act('afeCalc',()=>{const a=adcPlan(s.afe.low,s.afe.high,s.afe.bits,s.afe.target/100);$('afeCurrent').textContent=fmt(a.span);$('afeResult').textContent=JSON.stringify(a,null,2)})}
if(s.step===4){root.querySelectorAll('[data-point]').forEach(e=>e.onclick=()=>{s.selected=+e.dataset.point;render()});const q=s.points[s.selected];for(const [id,k] of [['pointRaw','raw'],['pointRef','reference'],['pointTemp','temp']])bindNum(id,v=>{q[k]=v;if(k==='raw'||k==='temp')delete q.acquisition;invalidate()});act('hwCapture',()=>runHardware(async()=>{stopLive();let v=device.model==='nsa2860x'||device.model==='nsa2860(x)'?await device.collect(12,true,s.t>1):await getSample(true);if(!v||!valid(v.pressureRaw))throw Error('Keine frischen ADC_S-Rohwerte. RAW_P/RAW_DATA_ON muss bereits gesetzt sein.');let temp=v.tempRaw;if(s.t>1&&device.model==='nsa2300'){const t=await device.single(0);temp=t.tempRaw;}if(s.t>1&&!valid(temp))throw Error('Keine Temperatur-Rohwerte. RAW_T muss aktiv sein.');q.raw=v.pressureRaw;q.temp=temp;q.acquisition={source:'chip',samples:v.samples||1,partId:device.identity,adapter:selectedAdapter,model:device.model,rawMin:v.pressureRawMin??v.pressureRaw,rawMax:v.pressureRawMax??v.pressureRaw,at:new Date().toISOString()};s.source=s.source==='synthetic'?'synthetic':'hardware-manual-reference';invalidate();render();message('Chipwerte übernommen. Referenz am Prüfplatz kontrollieren.','success')}));act('capture',()=>{if(!valid(q.raw)||!valid(q.reference)||(s.t>1&&!valid(q.temp)))throw Error('Messpunkt unvollständig.');if(s.selected<s.points.length-1){s.selected++;render();message('Messpunkt übernommen.','success')}else{go(5)}});act('synthetic',()=>{if(!confirm('Alle Messpunkte durch synthetische Daten ersetzen?'))return;s.source='synthetic';s.points=s.points.map((q,i)=>({...q,acquisition:undefined,raw:1000+8000*(i%s.p)/(s.p-1)+50*Math.floor(i/s.p),temp:1000+500*Math.floor(i/s.p)}));invalidate();render()})}
if(s.step===5){act('compute',()=>{invalidate();$('fitResult').textContent='Berechnung nicht abgeschlossen';s.fit=s.tk0?solveTk0(s.points):solve(s.points,s.p-1,s.t-1);$('fitResult').textContent=JSON.stringify({fit:s.fit,residuals:s.points.map(q=>predict(s.fit,q.raw,q.temp)-q.reference)},null,2);message('Offline-Koeffizienten berechnet.','success')});act('nativeCalc',()=>{const [a,b,c,d,e]=['nativeX1','nativeX2','nativeY1','nativeY2','nativeP0'].map(k=>$(k).valueAsNumber);const f=nsa2300TwoPoint(a,b,c,d,e);$('nativeResult').textContent=JSON.stringify({coefficients:f,check:[nsa2300Evaluate(f,a),nsa2300Evaluate(f,b)],registerEncoding:false},null,2)})}
if(s.step===9)bindLab();if(s.step===6)bindVerify();if(s.step===7)bindOutput();act('alarmSkip',()=>go(9));act('export',exportReport);act('finishCsv',()=>csv(s.results||[],'novosense-verification.csv'));act('finishPrint',()=>window.print());act('finishSave',()=>{if(!s.fit)throw Error('Zuerst berechnen.');archiveSave(report())});}
$('guidedHomeTop').onclick=home;$('guidedLaunchTop').hidden=false;$('guidedLaunchTop').onclick=toggleView;const studioSettings=window.SSC_UI.installSettingsPanel({panel:$('settingsPanel'),trigger:$('settingsOpen')});$('settingsTheme').value=document.documentElement.dataset.theme||'light';$('settingsTheme').onchange=e=>{document.documentElement.dataset.theme=e.target.value;try{localStorage.setItem('ssc-studio-theme-v1',e.target.value)}catch{}};try{$('expertMode').checked=localStorage.getItem('novo-expert')==='true'}catch{}$('expertMode').onchange=e=>{try{localStorage.setItem('novo-expert',String(e.target.checked))}catch{}render()};
resetLab();
if(navigator.serial)navigator.serial.addEventListener('disconnect',e=>{if(bridge.port&&(e.target===bridge.port||e.port===bridge.port)){stopLive();void bridge.close();device=null;boardInfo=null;latest=null;snapshot=null;render();updateHeader();message('USB-Verbindung getrennt.','warn')}});
render();
